from .core import *
from math import gcd,lcm

def make(family,v,n):
    a=2+v%4
    if family in ['divisors','find_divisors']:
        x=[12,18,20,24,30][v%5];div=[k for k in range(1,x+1) if x%k==0]
        tasks=[choice(f'{x} разделилось на {a if x%a==0 else 2} без остатка. Как называют число {a if x%a==0 else 2}?','Делитель',['Делитель','Остаток','Частное'],'Делитель делит число без остатка.'),
          multi(f'Выбери все делители числа {x} среди карточек.',[k for k in [1,2,3,4,5,6,7,8] if x%k==0],[1,2,3,4,5,6,7,8],'Проверь деление без остатка для каждой карточки.'),
          number(f'Какое наименьшее натуральное кратное числа {a+2}?',a+2,'Натуральные кратные получают умножением на 1, 2, 3…'),
          multi(f'Выбери все кратные {a+2}.',[(a+2)*k for k in [1,2,3]],[(a+2)*2,a+3,(a+2)*3,a+2,1],'Кратное делится на данное число без остатка.'),
          number(f'Сколько всего натуральных делителей у числа {x}?',len(div),'Выпиши пары множителей, затем убери повторы.'),
          number(f'На кружке {x} учеников. В каждой группе по 2. Сколько полных групп?',x//2,'Найди частное. Здесь все ученики распределяются без остатка.')]
        return package('Сортировщик делителей',['Делитель числа делит его без остатка. У натурального числа конечное число делителей.','Натуральные кратные числа можно продолжать бесконечно.'],['Делители 12','1, 2, 3, 4, 6, 12. Кратные 12: 12, 24, 36…'],'Выпиши все делители 24 и первые пять натуральных кратных 6.',tasks)
    if family=='primes':
        p=[7,11,13,17,19][v%5];c=[9,15,21,25,27][v%5]
        tasks=[choice('Сколько натуральных делителей у простого числа?','Два',['Один','Два','Три'],'Простое число больше 1 имеет только делители 1 и само себя.'),choice('Число 1 — простое или составное?','Ни простое, ни составное',['Простое','Составное','Ни простое, ни составное'],'У единицы только один натуральный делитель.'),multi('Выбери все простые числа.',[2,3,p],[1,2,3,4,p,c],'Проверяй наличие делителей между 1 и самим числом.'),choice(f'Число {c} — какое?','Составное',['Простое','Составное'],f'У {c} есть делитель, отличный от 1 и самого числа.'),number('Какое единственное чётное простое число?',2,'Все чётные числа больше 2 делятся и на 2, и на себя.'),choice(f'Алия назвала {p} составным, потому что оно нечётное. Верно ли это?','Нет',['Да','Нет'],'Чётность не определяет простоту: проверяй число делителей.')]
        return package('Охота за простыми числами',['Простое число имеет ровно два натуральных делителя.','Составное число имеет больше двух делителей; 1 не относится ни к одной группе.'],['Почему 9 составное?','Делители 9: 1, 3, 9. Их три.'],'Раздели числа от 1 до 20 на простые, составные и число 1. Объясни критерий.',tasks)
    if family in ['product_divisibility','sum_divisibility']:
        d=a+1;x=3*d;y=2*d
        tasks=[choice(f'{x} делится на {d}. Делится ли {x} × 5 на {d}?','Да',['Нет','Да'],'Если один множитель делится на число, произведение тоже делится.'),number(f'{x} × 5 ÷ {d} = ?',15,'Можно сначала разделить первый множитель.'),choice('Числа 2 и 3 не делятся на 6. Делится ли их произведение на 6?','Да',['Да','Нет'],'Свойство работает в одну сторону. 2 × 3 = 6.'),choice(f'{x} и {y} делятся на {d}. Делится ли их сумма на {d}?','Да',['Нет','Да'],'Если каждое слагаемое делится на число, сумма тоже делится.'),number(f'({x} − {y}) ÷ {d} = ?',1,'Разность двух кратных тоже делится на это число.'),choice('Сумма 1 + 5 делится на 3. Обязательно ли каждое слагаемое делится на 3?','Нет',['Да','Нет'],'Не делай обратный вывод без проверки отдельных чисел.')]
        if family=='sum_divisibility':tasks=tasks[3:]+tasks[:3]
        return package('Проверка математических правил',['Кратные одного числа можно складывать и вычитать: результат также делится на него.','Не путай верное свойство с обратным утверждением. Проверяй контрпример.'],['12 + 18 делится на 6','12 и 18 делятся на 6; сумма 30 тоже делится на 6.'],'Придумай верное утверждение о делимости и контрпример к его обратному утверждению.',tasks)
    if family in ['rules_2_5_10','rules_3_9']:
        x=120+10*v;z=123+9*v
        tasks=[choice(f'Делится ли {x+4} на 2?','Да',['Да','Нет'],'На 2 делятся числа с чётной последней цифрой.'),multi('Выбери числа, которые делятся на 5.',[x,x+5],[x+2,x,x+5,x+7],'Последняя цифра должна быть 0 или 5.'),choice(f'Делится ли {x+5} на 10?','Нет',['Да','Нет'],'Для делимости на 10 нужна последняя цифра 0.'),number(f'Найди сумму цифр числа {z}.',sum(map(int,str(z))),'Сложи цифры, а не разрядные значения.'),choice(f'Делится ли {z} на 3?','Да',['Нет','Да'],'Проверь, делится ли сумма цифр на 3.'),multi('Выбери все числа, делящиеся на 9.',[81,108,234],[81,108,123,234],'На 9 делятся числа, у которых сумма цифр делится на 9.')]
        if family=='rules_3_9':tasks=tasks[3:]+[choice(f'Делится ли {z} на 9?','Да' if z%9==0 else 'Нет',['Да','Нет'],'Делимость на 3 ещё не означает делимость на 9.'),choice('Число делится на 9. Обязательно ли оно делится на 3?','Да',['Да','Нет'],'9 само делится на 3.'),number('Какую цифру нужно поставить в 4□, чтобы число делилось на 9?',5,'Сумма цифр должна быть 9. Других подходящих сумм здесь нет.')]
        return package('Код последней цифры' if family=='rules_2_5_10' else 'Код суммы цифр',['Для 2, 5 и 10 проверяют последнюю цифру.','Для 3 и 9 проверяют сумму цифр.'],['Делится ли 234 на 9?','2 + 3 + 4 = 9. Значит, 234 делится на 9.'],'Придумай число, которое делится на 3, но не на 9, и объясни почему.',tasks)
    if family in ['powers','write_powers']:
        tasks=[choice(f'{a} × {a} × {a} можно записать как…',f'{a}³',[f'{a}³',f'3{a}',f'{a} + 3'],'Показатель степени показывает число одинаковых множителей.'),number(f'{a}² = ?',a*a,'Квадрат — число, умноженное само на себя.',check={'op':'×','args':[str(a),str(a)]}),number('2⁴ = ?',16,'Это 2 × 2 × 2 × 2, а не 2 × 4.'),choice('В записи 5³ число 3 — это…','Показатель',['Основание','Показатель','Результат'],'Основание — повторяющийся множитель.'),number(f'{a} × 100 + 4 × 10 + 2 = ?',a*100+42,'Сотни, десятки и единицы образуют десятичную запись.'),number(f'{a}³ = ?',a**3,'Запиши три одинаковых множителя и перемножь.')]
        if family=='write_powers':tasks[4]=number('Сколько множителей 3 в записи 3⁵?',5,'Показатель равен числу множителей, не числу знаков умножения.')
        return package('Башня степеней',['aⁿ — произведение n одинаковых множителей a.','Показатель степени не означает умножение основания на показатель.'],['3⁴','3 × 3 × 3 × 3 = 81.'],'Запиши число 204 в виде суммы разрядных слагаемых с использованием степеней 10.',tasks)
    if family=='factorization':
        x=[12,18,20,24,30][v%5];q=x;factors=[]
        for p in [2,3,5,7]:
            while q%p==0:factors.append(p);q//=p
        good=' × '.join(map(str,factors))
        tasks=[choice(f'С какого простого делителя можно начать разложение {x}?',str(factors[0]),[str(factors[0]),'1',str(x)],'Начинай с простого числа, на которое делится исходное.'),number(f'{x} ÷ {factors[0]} = ?',x//factors[0],'После первого деления продолжай разлагать частное.'),choice(f'Выбери разложение {x} на простые множители.',good,[good,f'1 × {x}',f'2 × {x}'],'Все множители должны быть простыми, а произведение — исходным числом.'),number(f'Сколько множителей в разложении {x}, если учитывать повторы?',len(factors),'Например, в 2 × 2 × 3 три множителя.'),number('2 × 2 × 2 × 3 = ?',24,'Перемножение проверяет разложение.'),choice('Разложение 36 = 4 × 9 уже состоит из простых множителей?','Нет',['Да','Нет'],'4 и 9 — составные, их нужно разложить дальше.')]
        return package('Дерево множителей',['Разлагай составные множители, пока не останутся только простые.','Проверь себя обратным умножением.'],['Разложи 18','18 = 2 × 9 = 2 × 3 × 3.'],'Построй дерево множителей числа 36 и проверь произведение.',tasks)
    if family in ['gcd_lcm','gcd_lcm_calc','gcd_lcm_words']:
        x,y=[(8,12),(12,18),(10,15),(6,9),(16,24)][v%5];g=gcd(x,y);l=lcm(x,y)
        tasks=[multi(f'Выбери все общие делители {x} и {y} среди карточек.',[k for k in [1,2,3,4,5,6] if x%k==0 and y%k==0],[1,2,3,4,5,6],'Общий делитель должен делить оба числа.'),number(f'Найди НОД({x}, {y}).',g,'Из общих делителей выбери наибольший.'),number(f'Найди НОК({x}, {y}).',l,'Найди наименьшее общее натуральное кратное.'),choice('Числа 8 и 15 взаимно простые?','Да',['Да','Нет'],'Взаимно простые числа имеют НОД, равный 1. Они не обязаны сами быть простыми.'),number(f'{x} красных и {y} синих деталей делят на одинаковые наборы без остатка. Какое наибольшее число наборов?',g,'Максимальное число одинаковых наборов даёт НОД.'),number(f'Сигналы повторяются через {x} и {y} минут. Сейчас совпали. Через сколько минут совпадут впервые снова?',l,'Первое общее время даёт НОК. Интервалы учебные.')]
        return package('Наборы и расписания',['НОД — наибольший общий делитель; НОК — наименьшее общее натуральное кратное.','В задаче сначала реши, нужен делитель или кратное.'],['12 и 18 деталей раскладывают в одинаковые наборы','НОД(12, 18) = 6: получится 6 наборов по 2 и 3 детали.'],'Составь одну задачу на НОД и одну на НОК. Объясни выбор действия.',tasks)
    raise ValueError(family)
